const IN_PROGRESS = ['pending', 'in_process', 'authorized'];
function decide(trip, payment) {
  if (!trip || trip.status !== 'completed') return 'none';
  if (payment.status === 'approved') {
    return payment.transaction_amount === trip.fare + (trip.tip ?? 0) ? 'pay' : 'mismatch';
  }
  if (IN_PROGRESS.includes(payment.status)) return 'none';
  return 'reject';
}
const base = { status: 'completed', fare: 10000 };
const cases = [
  ['sin propina, approved correcto (esperado pay)', base, { status: 'approved', transaction_amount: 10000 }],
  ['propina 500, in_process monto distinto (esperado none)', { ...base, tip: 500 }, { status: 'in_process', transaction_amount: 9999 }],
  ['propina 500, cancelled (esperado reject)', { ...base, tip: 500 }, { status: 'cancelled', transaction_amount: 10500 }],
  ['propina 500, rejected (esperado reject)', { ...base, tip: 500 }, { status: 'rejected', transaction_amount: 10500 }],
  ['propina 500, approved monto distinto (esperado mismatch)', { ...base, tip: 500 }, { status: 'approved', transaction_amount: 10000 }],
  ['viaje ya paid, approved (esperado none)', { ...base, status: 'paid' }, { status: 'approved', transaction_amount: 10000 }],
];
for (const [label, trip, pay] of cases) console.log(label.padEnd(58), '->', decide(trip, pay));
EOF
node "$SP/check-decide-propuesta.js"

